import React, { useState, useEffect } from 'react';
import PlayerRow from './PlayerRow';
import ChampionsLeagueFooter from './ChampionsLeagueFooter';
import ChampionsLeagueHeader from './ChampionsLeagueHeader';

const ChampionsLeagueScorers = () => {
  const [players, setPlayers] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [activeModal, setActiveModal] = useState(null);
  const [modalData, setModalData] = useState(null);
  const [selectedSection, setSelectedSection] = useState(null);
  const [selectedPlayer, setSelectedPlayer] = useState(null);
  const [activeView, setActiveView] = useState('home'); // 'home', 'player-detail', 'player-teams', 'player-seasons'
  const [detailPlayer, setDetailPlayer] = useState(null);

  // Cargar datos del archivo JSON
  useEffect(() => {
    setIsLoading(true);

    fetch('/data/top-champions-league-scorers.json')
      .then(response => {
        if (!response.ok) {
          throw new Error('Error al cargar los datos de los goleadores');
        }
        return response.json();
      })
      .then(data => {
        // Transformar los datos al formato que necesitamos
        const formattedPlayers = data.map((player, index) => ({
          position: index + 1,
          name: player.nombre,
          team: player.equipos.map(t => t.equipo).join('/'),
          goals: player.goles_totales,
          fullData: player // Guardamos todos los datos para usar en los modales
        }));
        setPlayers(formattedPlayers);
        setIsLoading(false);
      })
      .catch(err => {
        console.error('Error fetching data:', err);
        setError(err.message);
        setIsLoading(false);
      });
  }, []);

  // Función para manejar la navegación
  const handleNavigate = (view, player = null) => {
    setActiveView(view);
    if (player) {
      setDetailPlayer(player);
    }
    setSelectedSection(null);
    setSelectedPlayer(null);
  };

  // Función para seleccionar un jugador y mostrar sus detalles
  const showPlayerDetails = (player) => {
    setDetailPlayer(player);
    setActiveView('player-detail');
  };

  // Función para mostrar los equipos de un jugador
  const showPlayerTeams = (player) => {
    setDetailPlayer(player);
    setActiveView('player-teams');
  };

  // Función para mostrar las temporadas de un jugador
  const showPlayerSeasons = (player) => {
    setDetailPlayer(player);
    setActiveView('player-seasons');
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-champions-blue">
        <div className="text-center">
          <div className="w-32 h-32 mx-auto mb-6 rounded-xl shadow-lg p-2 border border-champions-gold/30 bg-champions-blue/80">
            <img 
              src="/images/logos/cc.png" 
              alt="Champions League Logo" 
              className="w-full h-full object-contain animate-pulse"
            />
          </div>
          <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-champions-gold mx-auto"></div>
          <p className="mt-4 text-lg text-white">
            <span className="champions-star">★</span> Cargando goleadores <span className="champions-star">★</span>
          </p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-champions-blue">
        <div className="text-center text-red-500">
          <p className="text-2xl font-bold text-white">Error al cargar los datos</p>
          <p className="mt-2 text-champions-gold">{error}</p>
        </div>
      </div>
    );
  }

  // Componente de Modal
  const Modal = ({ isOpen, onClose, children }) => {
    if (!isOpen) return null;

    return (
      <div className="fixed inset-0 flex items-center justify-center z-50 bg-black bg-opacity-60">
        <div className="bg-white rounded-lg shadow-lg p-6 max-w-md w-full m-4 transform transition-all animate-fadeIn">
          <div className="flex justify-end">
            <button 
              onClick={onClose}
              className="text-gray-500 hover:text-champions-blue"
            >
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>
          {children}
        </div>
      </div>
    );
  };

  // Renderizar la vista de inicio (tabla de goleadores)
  const renderHomeView = () => (
    <main className="flex-grow py-8">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="glass-effect rounded-lg overflow-hidden shadow-lg">
          <div className="p-6 bg-champions-blue text-white relative overflow-hidden">
            <div className="absolute top-0 right-0 opacity-10 w-64 h-64">
              {Array(5).fill('').map((_, i) => (
                <div key={i} 
                  className="absolute text-champions-gold"
                  style={{
                    fontSize: `${Math.random() * 20 + 20}px`,
                    top: `${Math.random() * 100}%`,
                    left: `${Math.random() * 100}%`,
                    opacity: Math.random() * 0.5 + 0.2,
                    transform: `rotate(${Math.random() * 360}deg)`
                  }}
                >★</div>
              ))}
            </div>

            <div className="flex items-center mb-4">
              <div className="w-16 h-16 mr-4 overflow-hidden rounded-lg shadow-md border border-champions-gold/30 bg-champions-blue/70">
                <img 
                  src="/images/logos/cc.png" 
                  alt="Champions League Logo" 
                  className="w-full h-full object-contain transform hover:scale-105 transition-transform duration-300"
                />
              </div>
              <h1 className="text-3xl font-bold">
                Máximos Goleadores de la UEFA Champions League
              </h1>
            </div>
            <p className="mt-2 text-blue-100">
              <span className="trophy-icon">🏆</span> 
              Histórico de jugadores con más goles en la competición
            </p>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-100">
                <tr>
                  <th className="py-3 px-4 text-left text-xs font-medium text-champions-blue uppercase tracking-wider">Pos</th>
                  <th className="py-3 px-4 text-left text-xs font-medium text-champions-blue uppercase tracking-wider">Jugador</th>
                  <th className="py-3 px-4 text-left text-xs font-medium text-champions-blue uppercase tracking-wider">Equipos</th>
                  <th className="py-3 px-4 text-center text-xs font-medium text-champions-blue uppercase tracking-wider">
                    <span className="flex items-center justify-center">
                      <span className="trophy-icon text-lg">⚽</span> Goles
                    </span>
                  </th>
                  <th className="py-3 px-4 text-center text-xs font-medium text-champions-blue uppercase tracking-wider">Acciones</th>
                </tr>
              </thead>
              <tbody>
                {players.map((player) => (
                  <tr 
                    key={player.position}
                    className="hover:bg-blue-50 border-b border-gray-200 group"
                  >
                    <td className="py-3 px-4 text-champions-blue font-bold">{player.position}</td>
                    <td className="py-3 px-4">
                      <div className="flex items-center">
                        <div className="h-10 w-10 rounded-full overflow-hidden border-2 border-champions-blue mr-3">
                          <img 
                            src={player.fullData?.image || "/images/players/default.jpg"} 
                            alt={player.name} 
                            className="h-full w-full object-cover"
                            onError={(e) => {
                              e.target.onerror = null;
                              e.target.src = '/images/players/default.jpg';
                            }}
                          />
                        </div>
                        <span className="font-medium text-gray-900">{player.name}</span>
                      </div>
                    </td>
                    <td className="py-3 px-4 text-gray-500">{player.team}</td>
                    <td className="py-3 px-4 text-center font-bold text-champions-blue">{player.goals}</td>
                    <td className="py-3 px-4 text-center">
                      <div className="flex justify-center space-x-2">
                        <button
                          onClick={() => showPlayerDetails(player)}
                          className="bg-champions-blue text-white px-3 py-1 rounded-md text-xs hover:bg-blue-700 transition-colors"
                        >
                          Detalles
                        </button>
                        <button
                          onClick={() => showPlayerTeams(player)}
                          className="bg-champions-gold text-white px-3 py-1 rounded-md text-xs hover:bg-yellow-600 transition-colors"
                        >
                          Equipos
                        </button>
                        <button
                          onClick={() => showPlayerSeasons(player)}
                          className="bg-green-600 text-white px-3 py-1 rounded-md text-xs hover:bg-green-700 transition-colors"
                        >
                          Temporadas
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </main>
  );

  // Renderizar la vista de detalles del jugador
  const renderPlayerDetailView = () => {
    if (!detailPlayer) return <div>No hay jugador seleccionado</div>;

    const playerData = detailPlayer.fullData || {
      name: detailPlayer.name,
      country: 'Desconocido',
      birthdate: 'Desconocido',
      image: '/images/players/default.jpg',
      teams: detailPlayer.team.split(',').map(team => team.trim()),
      goals: detailPlayer.goals,
      appearances: 'Desconocido',
      finalAppearances: 0,
      championships: 0,
      bio: 'Información no disponible'
    };

    return (
      <main className="flex-grow py-8">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="bg-white rounded-lg shadow-lg overflow-hidden">
            {/* Cabecera del perfil */}
            <div className="bg-champions-blue text-white p-6 lg:p-8 relative">
              <div className="flex flex-col md:flex-row items-center">
                <div className="w-32 h-32 md:w-48 md:h-48 rounded-full overflow-hidden border-4 border-white/50 shadow-lg mb-4 md:mb-0 md:mr-8">
                  <img 
                    src={playerData.image} 
                    alt={playerData.name} 
                    className="w-full h-full object-cover"
                    onError={(e) => {
                      e.target.onerror = null;
                      e.target.src = '/images/players/default.jpg';
                    }}
                  />
                </div>

                <div className="flex-1 text-center md:text-left">
                  <h2 className="text-3xl md:text-4xl font-bold mb-2">{playerData.name}</h2>
                  <div className="flex flex-wrap justify-center md:justify-start items-center mb-4">
                    <span className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium bg-blue-900 text-white mr-2 mb-2">
                      {playerData.country}
                    </span>
                    <span className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium bg-blue-900 text-white mr-2 mb-2">
                      {typeof playerData.birthdate === 'string' ? playerData.birthdate : 'Desconocido'}
                    </span>
                  </div>

                  <div className="flex flex-wrap justify-center md:justify-start">
                    {Array.isArray(playerData.teams) && playerData.teams.map((team, idx) => (
                      <span 
                        key={idx} 
                        className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium bg-blue-700 text-white mr-2 mb-2"
                      >
                        {team}
                      </span>
                    ))}
                  </div>
                </div>

                <div className="mt-4 md:mt-0 flex flex-col items-center">
                  <div className="text-4xl md:text-5xl font-bold text-champions-gold">{playerData.goals}</div>
                  <div className="text-sm md:text-base text-blue-200">Goles en Champions</div>
                </div>
              </div>
            </div>

            {/* Estadísticas */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-6 bg-gray-50">
              <div className="bg-white p-4 rounded-lg shadow text-center">
                <div className="text-2xl font-bold text-champions-blue">{playerData.appearances || 'N/A'}</div>
                <div className="text-sm text-gray-500">Partidos</div>
              </div>

              <div className="bg-white p-4 rounded-lg shadow text-center">
                <div className="text-2xl font-bold text-champions-blue">{playerData.goals}</div>
                <div className="text-sm text-gray-500">Goles</div>
              </div>

              <div className="bg-white p-4 rounded-lg shadow text-center">
                <div className="text-2xl font-bold text-champions-blue">{playerData.finalAppearances || 0}</div>
                <div className="text-sm text-gray-500">Finales</div>
              </div>

              <div className="bg-white p-4 rounded-lg shadow text-center">
                <div className="text-2xl font-bold text-champions-blue">{playerData.championships || 0}</div>
                <div className="text-sm text-gray-500">Títulos</div>
              </div>
            </div>

            {/* Biografía */}
            <div className="p-6 lg:p-8">
              <h3 className="text-xl font-bold text-champions-blue mb-4">Biografía y Carrera</h3>
              <p className="text-gray-700 mb-4">{playerData.bio || 'Información no disponible'}</p>
            </div>

            {/* Botones de navegación */}
            <div className="p-6 bg-gray-50 flex justify-center space-x-4">
              <button
                onClick={() => showPlayerTeams(detailPlayer)}
                className="bg-champions-gold hover:bg-yellow-600 text-white px-6 py-2 rounded-md font-medium transition-colors"
              >
                Ver Equipos
              </button>
              <button
                onClick={() => showPlayerSeasons(detailPlayer)}
                className="bg-green-600 hover:bg-green-700 text-white px-6 py-2 rounded-md font-medium transition-colors"
              >
                Ver Temporadas
              </button>
            </div>
          </div>
        </div>
      </main>
    );
  };

  return (
    <div className="min-h-screen flex flex-col">
      <ChampionsLeagueHeader 
        activeView={activeView}
        onNavigate={handleNavigate}
      />

      {/* Renderizar la vista activa */}
      {activeView === 'home' && renderHomeView()}
      {activeView === 'player-detail' && renderPlayerDetailView()}
      {activeView === 'player-teams' && <div className="p-8">Información de equipos del jugador (en desarrollo)</div>}
      {activeView === 'player-seasons' && <div className="p-8">Información de temporadas del jugador (en desarrollo)</div>}

      <ChampionsLeagueFooter />
    </div>
  );
};

export default ChampionsLeagueScorers;
